Creating a complex smart contract involves a deep understanding of programming languages like Solidity, which is used for writing smart contracts on the Ethereum blockchain, and a good grasp of blockchain concepts. Below is a simplified example of a smart contract written in Solidity that could be used to create a decentralized voting system. This is a basic illustration and real-world applications would require more robust security measures and features.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract VotingSystem {
    struct Candidate {
        string name;
        uint voteCount;
    }

    struct Voter {
        bool authorized;
        bool voted;
        uint vote;
    }

    address public owner;
    string public electionName;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    uint public totalCandidates;

    modifier ownerOnly() {
        require(msg.sender == owner, "Only the owner can call this function.");
        _;
    }

    constructor(string memory _name) {
        owner = msg.sender;
        electionName = _name;
    }

    function addCandidate(string memory _name) public ownerOnly {
        candidates.push(Candidate({name: _name, voteCount: 0}));
        totalCandidates++;
    }

    function authorizeVoter(address _voter) public ownerOnly {
        require(!voters[_voter].voted, "The voter has already voted.");
        voters[_voter].authorized = true;
    }

    function vote(uint _voteIndex) public {
        require(!voters[msg.sender].voted, "You have already voted.");
        require(voters[msg.sender].authorized, "You are not authorized to vote.");

        voters[msg.sender].voted = true;
        voters[msg.sender].vote = _voteIndex;

        candidates[_voteIndex].voteCount++;
    }

    function end() public ownerOnly {
        // Logic to end the election and declare the winner
    }
}
```

This contract allows the owner to create an election, add candidates, authorize voters, and cast votes. It is a basic example and does not include all the features and security measures needed for a production-ready smart contract. Always have a smart contract audited by professionals before deploying it on the mainnet.

