```c
#include <stdio.h>

// Define error codes
#define SUCCESS 0
#define ERROR_INVALID_INPUT -1
#define ERROR_OUT_OF_MEMORY -2

// Function that might fail
int performOperation(int input) {
    if (input < 0) {
        // Input is invalid, return an error code
        return ERROR_INVALID_INPUT;
    }

    // Perform the operation (omitted for brevity)

    // If everything is fine, return success
    return SUCCESS;
}

int main() {
    int result = performOperation(-1); // Example of invalid input

    if (result != SUCCESS) {
        // Handle the error based on the error code
        switch (result) {
            case ERROR_INVALID_INPUT:
                printf("Error: Invalid input provided.\n");
                break;
            case ERROR_OUT_OF_MEMORY:
                printf("Error: Out of memory.\n");
                break;
            default:
                printf("An unknown error occurred.\n");
                break;
        }
    } else {
        // Continue with the rest of the program
    }

    return 0;
}
```

In this example, `performOperation` returns an error code if the input is invalid. The caller, `main`, checks the return value and handles the error accordingly. This is a common pattern in C for error handling, as C does not have built-in exceptions like some other languages.

