        String mostPopularColor = Collections.max(colorCountMap.entrySet(), Comparator.comparingInt(Map.Entry::getValue)).getKey();

        // Return a map with the most popular color and its count
        Map<String, Integer> result = new HashMap<>();
        result.put(mostPopularColor, colorCountMap.get(mostPopularColor));

        return result;
    }
}
```

